Dataspatium.assets.register("presets/api/oecd.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"oecd\",\n  \"name\": \"OECD\",\n  \"publisher\": \"OECD\",\n  \"description\": \"Statistik för OECD-länderna från OECD Data Explorer i formatet SDMX-JSON: arbetsmarknad, nationalräkenskaper, priser och mycket mer. Varje observation blir en rad med dimensionernas koder och namn, period och värde.\",\n  \"docs\": \"https://www.oecd.org/en/data/insights/data-explainers/2024/09/api.html\",\n  \"license\": {\n    \"name\": \"CC BY 4.0\",\n    \"url\": \"https://creativecommons.org/licenses/by/4.0/\"\n  },\n  \"level\": 1,\n  \"country\": \"INT\",\n  \"baseUrl\": \"https://sdmx.oecd.org/public/rest/data\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 1, \"perSeconds\": 1 },\n  \"endpoints\": [\n    {\n      \"id\": \"unemployment\",\n      \"name\": \"Arbetslöshet per månad\",\n      \"description\": \"Säsongsrensad arbetslöshet i procent av arbetskraften, 15 år och äldre, per land och månad (dataflödet DF_IALFS_UNE_M).\",\n      \"method\": \"GET\",\n      \"path\": \"/OECD.SDD.TPS,DSD_LFS@DF_IALFS_UNE_M,1.0/{countries}..._Z.Y._T.Y_GE15..M\",\n      \"params\": [\n        { \"name\": \"countries\", \"in\": \"path\", \"label\": \"Länder\", \"type\": \"multi\", \"join\": \"+\", \"required\": true, \"default\": \"SWE,NOR,DNK,FIN,ISL\", \"example\": \"SWE,NOR,DNK,FIN,ISL\", \"help\": \"ISO-koder med tre bokstäver åtskilda med kommatecken, till exempel SWE,NOR,DEU.\" },\n        { \"name\": \"startPeriod\", \"in\": \"query\", \"label\": \"Från period\", \"type\": \"string\", \"example\": \"2020-01\" },\n        { \"name\": \"endPeriod\", \"in\": \"query\", \"label\": \"Till period\", \"type\": \"string\" },\n        { \"name\": \"lastNObservations\", \"in\": \"query\", \"label\": \"Bara de senaste n observationerna\", \"type\": \"number\" },\n        { \"name\": \"format\", \"in\": \"query\", \"type\": \"string\", \"default\": \"jsondata\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"sdmx\" },\n      \"dataset\": { \"name\": \"OECD arbetslöshet {countries}\" }\n    },\n    {\n      \"id\": \"gdp\",\n      \"name\": \"BNP-tillväxt per kvartal\",\n      \"description\": \"Förändring av BNP i fasta priser mot samma kvartal året innan, per land (dataflödet DF_QNA_EXPENDITURE_GROWTH_OECD).\",\n      \"method\": \"GET\",\n      \"path\": \"/OECD.SDD.NAD,DSD_NAMAIN1@DF_QNA_EXPENDITURE_GROWTH_OECD,1.0/Q..{countries}.S1..B1GQ......GY.\",\n      \"params\": [\n        { \"name\": \"countries\", \"in\": \"path\", \"label\": \"Länder\", \"type\": \"multi\", \"join\": \"+\", \"required\": true, \"default\": \"SWE,NOR,DNK,FIN,ISL\", \"example\": \"SWE,NOR,DNK,FIN,ISL\", \"help\": \"ISO-koder med tre bokstäver åtskilda med kommatecken, till exempel SWE,NOR,DEU.\" },\n        { \"name\": \"startPeriod\", \"in\": \"query\", \"label\": \"Från period\", \"type\": \"string\", \"example\": \"2015-Q1\" },\n        { \"name\": \"endPeriod\", \"in\": \"query\", \"label\": \"Till period\", \"type\": \"string\" },\n        { \"name\": \"lastNObservations\", \"in\": \"query\", \"label\": \"Bara de senaste n observationerna\", \"type\": \"number\" },\n        { \"name\": \"format\", \"in\": \"query\", \"type\": \"string\", \"default\": \"jsondata\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"sdmx\" },\n      \"dataset\": { \"name\": \"OECD BNP-tillväxt {countries}\" }\n    },\n    {\n      \"id\": \"data\",\n      \"name\": \"Hämta dataflöde (SDMX)\",\n      \"description\": \"Valfritt dataflöde och nyckel från OECD Data Explorer. Under Developer API i Data Explorer visas adressen för en tabell; dataflödet är delen efter /data/ och nyckeln delen efter nästa snedstreck.\",\n      \"method\": \"GET\",\n      \"path\": \"/{flow}/{key}\",\n      \"params\": [\n        { \"name\": \"flow\", \"in\": \"path\", \"label\": \"Dataflöde\", \"type\": \"string\", \"required\": true, \"example\": \"OECD.SDD.TPS,DSD_LFS@DF_IALFS_UNE_M,1.0\" },\n        { \"name\": \"key\", \"in\": \"path\", \"label\": \"Nyckel\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"SWE+NOR..._Z.Y._T.Y_GE15..M\", \"help\": \"Dimensionernas koder åtskilda med punkt; + väljer flera koder och en tom position alla.\" },\n        { \"name\": \"startPeriod\", \"in\": \"query\", \"label\": \"Från period\", \"type\": \"string\" },\n        { \"name\": \"endPeriod\", \"in\": \"query\", \"label\": \"Till period\", \"type\": \"string\" },\n        { \"name\": \"lastNObservations\", \"in\": \"query\", \"label\": \"Bara de senaste n observationerna\", \"type\": \"number\" },\n        { \"name\": \"format\", \"in\": \"query\", \"type\": \"string\", \"default\": \"jsondata\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"sdmx\" },\n      \"dataset\": { \"name\": \"OECD {flow}\" }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"OECD\",\n      \"publisher\": \"OECD\",\n      \"description\": \"Statistics for the OECD countries from the OECD Data Explorer in the SDMX-JSON format: labour market, national accounts, prices and much more. Every observation becomes a row with the codes and names of the dimensions, the period and the value.\",\n      \"endpoints\": {\n        \"unemployment\": { \"name\": \"Unemployment per month\", \"description\": \"Seasonally adjusted unemployment as a percentage of the labour force, aged 15 and over, per country and month (dataflow DF_IALFS_UNE_M).\",\n          \"params\": { \"countries\": { \"label\": \"Countries\", \"help\": \"Three-letter ISO codes separated by commas, for example SWE,NOR,DEU.\" }, \"startPeriod\": { \"label\": \"From period\" }, \"endPeriod\": { \"label\": \"To period\" }, \"lastNObservations\": { \"label\": \"Only the latest n observations\" } } },\n        \"gdp\": { \"name\": \"GDP growth per quarter\", \"description\": \"Change of GDP in constant prices against the same quarter a year earlier, per country (dataflow DF_QNA_EXPENDITURE_GROWTH_OECD).\",\n          \"params\": { \"countries\": { \"label\": \"Countries\", \"help\": \"Three-letter ISO codes separated by commas, for example SWE,NOR,DEU.\" }, \"startPeriod\": { \"label\": \"From period\" }, \"endPeriod\": { \"label\": \"To period\" }, \"lastNObservations\": { \"label\": \"Only the latest n observations\" } } },\n        \"data\": { \"name\": \"Fetch dataflow (SDMX)\", \"description\": \"Any dataflow and key from the OECD Data Explorer. Under Developer API the Data Explorer shows the address of a table; the dataflow is the part after /data/ and the key the part after the next slash.\",\n          \"params\": { \"flow\": { \"label\": \"Dataflow\" }, \"key\": { \"label\": \"Key\", \"help\": \"The codes of the dimensions separated by full stops; + chooses several codes and an empty position all of them.\" }, \"startPeriod\": { \"label\": \"From period\" }, \"endPeriod\": { \"label\": \"To period\" }, \"lastNObservations\": { \"label\": \"Only the latest n observations\" } } }\n      },\n      \"dataset\": { \"unemployment\": \"OECD unemployment {countries}\", \"gdp\": \"OECD GDP growth {countries}\", \"data\": \"OECD {flow}\" }\n    },\n    \"da\": {\n      \"name\": \"OECD\",\n      \"publisher\": \"OECD\",\n      \"description\": \"Statistik for OECD-landene fra OECD Data Explorer i formatet SDMX-JSON: arbejdsmarked, nationalregnskab, priser og meget mere. Hver observation bliver en række med dimensionernes koder og navne, periode og værdi.\",\n      \"endpoints\": {\n        \"unemployment\": { \"name\": \"Ledighed pr. måned\", \"description\": \"Sæsonkorrigeret ledighed i procent af arbejdsstyrken, 15 år og ældre, pr. land og måned (dataflowet DF_IALFS_UNE_M).\",\n          \"params\": { \"countries\": { \"label\": \"Lande\", \"help\": \"ISO-koder på tre bogstaver adskilt med kommaer, for eksempel DNK,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Fra periode\" }, \"endPeriod\": { \"label\": \"Til periode\" }, \"lastNObservations\": { \"label\": \"Kun de seneste n observationer\" } } },\n        \"gdp\": { \"name\": \"BNP-vækst pr. kvartal\", \"description\": \"Ændring i BNP i faste priser i forhold til samme kvartal året før, pr. land (dataflowet DF_QNA_EXPENDITURE_GROWTH_OECD).\",\n          \"params\": { \"countries\": { \"label\": \"Lande\", \"help\": \"ISO-koder på tre bogstaver adskilt med kommaer, for eksempel DNK,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Fra periode\" }, \"endPeriod\": { \"label\": \"Til periode\" }, \"lastNObservations\": { \"label\": \"Kun de seneste n observationer\" } } },\n        \"data\": { \"name\": \"Hent dataflow (SDMX)\", \"description\": \"Vilkårligt dataflow og nøgle fra OECD Data Explorer. Under Developer API viser Data Explorer adressen for en tabel; dataflowet er delen efter /data/ og nøglen delen efter næste skråstreg.\",\n          \"params\": { \"flow\": { \"label\": \"Dataflow\" }, \"key\": { \"label\": \"Nøgle\", \"help\": \"Dimensionernes koder adskilt med punktum; + vælger flere koder og en tom position dem alle.\" }, \"startPeriod\": { \"label\": \"Fra periode\" }, \"endPeriod\": { \"label\": \"Til periode\" }, \"lastNObservations\": { \"label\": \"Kun de seneste n observationer\" } } }\n      },\n      \"dataset\": { \"unemployment\": \"OECD ledighed {countries}\", \"gdp\": \"OECD BNP-vækst {countries}\", \"data\": \"OECD {flow}\" }\n    },\n    \"nb\": {\n      \"name\": \"OECD\",\n      \"publisher\": \"OECD\",\n      \"description\": \"Statistikk for OECD-landene fra OECD Data Explorer i formatet SDMX-JSON: arbeidsmarked, nasjonalregnskap, priser og mye mer. Hver observasjon blir en rad med dimensjonenes koder og navn, periode og verdi.\",\n      \"endpoints\": {\n        \"unemployment\": { \"name\": \"Arbeidsledighet per måned\", \"description\": \"Sesongjustert arbeidsledighet i prosent av arbeidsstyrken, 15 år og eldre, per land og måned (dataflyten DF_IALFS_UNE_M).\",\n          \"params\": { \"countries\": { \"label\": \"Land\", \"help\": \"ISO-koder med tre bokstaver skilt med komma, for eksempel NOR,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Fra periode\" }, \"endPeriod\": { \"label\": \"Til periode\" }, \"lastNObservations\": { \"label\": \"Bare de siste n observasjonene\" } } },\n        \"gdp\": { \"name\": \"BNP-vekst per kvartal\", \"description\": \"Endring i BNP i faste priser mot samme kvartal året før, per land (dataflyten DF_QNA_EXPENDITURE_GROWTH_OECD).\",\n          \"params\": { \"countries\": { \"label\": \"Land\", \"help\": \"ISO-koder med tre bokstaver skilt med komma, for eksempel NOR,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Fra periode\" }, \"endPeriod\": { \"label\": \"Til periode\" }, \"lastNObservations\": { \"label\": \"Bare de siste n observasjonene\" } } },\n        \"data\": { \"name\": \"Hent dataflyt (SDMX)\", \"description\": \"Valgfri dataflyt og nøkkel fra OECD Data Explorer. Under Developer API viser Data Explorer adressen til en tabell; dataflyten er delen etter /data/ og nøkkelen delen etter neste skråstrek.\",\n          \"params\": { \"flow\": { \"label\": \"Dataflyt\" }, \"key\": { \"label\": \"Nøkkel\", \"help\": \"Dimensjonenes koder skilt med punktum; + velger flere koder og en tom posisjon alle.\" }, \"startPeriod\": { \"label\": \"Fra periode\" }, \"endPeriod\": { \"label\": \"Til periode\" }, \"lastNObservations\": { \"label\": \"Bare de siste n observasjonene\" } } }\n      },\n      \"dataset\": { \"unemployment\": \"OECD arbeidsledighet {countries}\", \"gdp\": \"OECD BNP-vekst {countries}\", \"data\": \"OECD {flow}\" }\n    },\n    \"fi\": {\n      \"name\": \"OECD\",\n      \"publisher\": \"OECD\",\n      \"description\": \"OECD-maiden tilastoja OECD Data Explorerista SDMX-JSON-muodossa: työmarkkinat, kansantalouden tilinpito, hinnat ja paljon muuta. Jokaisesta havainnosta tulee rivi, jossa ovat ulottuvuuksien koodit ja nimet, ajanjakso ja arvo.\",\n      \"endpoints\": {\n        \"unemployment\": { \"name\": \"Työttömyys kuukausittain\", \"description\": \"Kausitasoitettu työttömyysaste prosentteina työvoimasta, 15 vuotta täyttäneet, maittain ja kuukausittain (tietovirta DF_IALFS_UNE_M).\",\n          \"params\": { \"countries\": { \"label\": \"Maat\", \"help\": \"Kolmikirjaimiset ISO-koodit pilkuin erotettuina, esimerkiksi FIN,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Alkaen\" }, \"endPeriod\": { \"label\": \"Päättyen\" }, \"lastNObservations\": { \"label\": \"Vain n viimeisintä havaintoa\" } } },\n        \"gdp\": { \"name\": \"BKT:n kasvu neljännesvuosittain\", \"description\": \"Kiintein hinnoin lasketun BKT:n muutos edellisen vuoden vastaavaan neljännekseen, maittain (tietovirta DF_QNA_EXPENDITURE_GROWTH_OECD).\",\n          \"params\": { \"countries\": { \"label\": \"Maat\", \"help\": \"Kolmikirjaimiset ISO-koodit pilkuin erotettuina, esimerkiksi FIN,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Alkaen\" }, \"endPeriod\": { \"label\": \"Päättyen\" }, \"lastNObservations\": { \"label\": \"Vain n viimeisintä havaintoa\" } } },\n        \"data\": { \"name\": \"Hae tietovirta (SDMX)\", \"description\": \"Mikä tahansa OECD Data Explorerin tietovirta ja avain. Data Explorer näyttää taulukon osoitteen kohdassa Developer API; tietovirta on /data/-osan jälkeinen osa ja avain seuraavan kauttaviivan jälkeinen osa.\",\n          \"params\": { \"flow\": { \"label\": \"Tietovirta\" }, \"key\": { \"label\": \"Avain\", \"help\": \"Ulottuvuuksien koodit pisteillä erotettuina; + valitsee useita koodeja ja tyhjä kohta kaikki.\" }, \"startPeriod\": { \"label\": \"Alkaen\" }, \"endPeriod\": { \"label\": \"Päättyen\" }, \"lastNObservations\": { \"label\": \"Vain n viimeisintä havaintoa\" } } }\n      },\n      \"dataset\": { \"unemployment\": \"OECD työttömyys {countries}\", \"gdp\": \"OECD BKT:n kasvu {countries}\", \"data\": \"OECD {flow}\" }\n    },\n    \"is\": {\n      \"name\": \"OECD\",\n      \"publisher\": \"OECD\",\n      \"description\": \"Tölfræði fyrir OECD-löndin úr OECD Data Explorer á SDMX-JSON-sniði: vinnumarkaður, þjóðhagsreikningar, verðlag og margt fleira. Hver athugun verður að röð með kóðum og heitum víddanna, tímabili og gildi.\",\n      \"endpoints\": {\n        \"unemployment\": { \"name\": \"Atvinnuleysi eftir mánuðum\", \"description\": \"Árstíðaleiðrétt atvinnuleysi sem hlutfall af vinnuafli, 15 ára og eldri, eftir löndum og mánuðum (gagnaflæðið DF_IALFS_UNE_M).\",\n          \"params\": { \"countries\": { \"label\": \"Lönd\", \"help\": \"Þriggja stafa ISO-kóðar aðgreindir með kommum, til dæmis ISL,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Frá tímabili\" }, \"endPeriod\": { \"label\": \"Til tímabils\" }, \"lastNObservations\": { \"label\": \"Aðeins n nýjustu athuganirnar\" } } },\n        \"gdp\": { \"name\": \"Hagvöxtur eftir ársfjórðungum\", \"description\": \"Breyting landsframleiðslu á föstu verðlagi frá sama ársfjórðungi árið áður, eftir löndum (gagnaflæðið DF_QNA_EXPENDITURE_GROWTH_OECD).\",\n          \"params\": { \"countries\": { \"label\": \"Lönd\", \"help\": \"Þriggja stafa ISO-kóðar aðgreindir með kommum, til dæmis ISL,SWE,DEU.\" }, \"startPeriod\": { \"label\": \"Frá tímabili\" }, \"endPeriod\": { \"label\": \"Til tímabils\" }, \"lastNObservations\": { \"label\": \"Aðeins n nýjustu athuganirnar\" } } },\n        \"data\": { \"name\": \"Sækja gagnaflæði (SDMX)\", \"description\": \"Hvaða gagnaflæði og lykill sem er úr OECD Data Explorer. Undir Developer API sýnir Data Explorer slóð töflu; gagnaflæðið er hlutinn á eftir /data/ og lykillinn hlutinn á eftir næsta skástriki.\",\n          \"params\": { \"flow\": { \"label\": \"Gagnaflæði\" }, \"key\": { \"label\": \"Lykill\", \"help\": \"Kóðar víddanna aðgreindir með punktum; + velur marga kóða og auð staða alla.\" }, \"startPeriod\": { \"label\": \"Frá tímabili\" }, \"endPeriod\": { \"label\": \"Til tímabils\" }, \"lastNObservations\": { \"label\": \"Aðeins n nýjustu athuganirnar\" } } }\n      },\n      \"dataset\": { \"unemployment\": \"OECD atvinnuleysi {countries}\", \"gdp\": \"OECD hagvöxtur {countries}\", \"data\": \"OECD {flow}\" }\n    }\n  }\n}\n");
